BEGIN;
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Fastness of Body' THEN 'Armatrutz' ELSE "LocaText" END WHERE "LocaId" = 'Armatrutz';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Move as the Lightning' THEN 'Axxeleratus Ligthning Fast' ELSE "LocaText" END WHERE "LocaId" = 'AxxeleratusBlitzgeschwind';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Roundhouse' THEN 'Roundhouse Blow' ELSE "LocaText" END WHERE "LocaId" = 'Befreiungsschlag';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Thunderbolt' THEN 'Fulminictus' ELSE "LocaText" END WHERE "LocaId" = 'Console_Output_ApplySP_Magic_Fulminictus';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Culminatio Ball of Lightning' THEN 'Kulminatio' ELSE "LocaText" END WHERE "LocaId" = 'Console_Output_ApplySP_Magic_Lighting_Ball';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Eclipsus Shadow Force' THEN 'Ecliptifactus Shadow Force' ELSE "LocaText" END WHERE "LocaId" = 'EcliptifactusSchattenkraft';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Ice Cold Warrior' THEN 'Ice and Cold, Heart of Warrior' ELSE "LocaText" END WHERE "LocaId" = 'EiseskaelteKaempferherz';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Fandango of Fireflies' THEN 'Favilludo Dance of Sparks' ELSE "LocaText" END WHERE "LocaId" = 'FavilludoFunkentanz';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Light in the Darkness' THEN 'Flim Flam Flare' ELSE "LocaText" END WHERE "LocaId" = 'FlimFlamFunkel';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Thunderbolt' THEN 'Fulminictus' ELSE "LocaText" END WHERE "LocaId" = 'FulminictusDonnerkeil';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Healing Mage' THEN 'Wizard' ELSE "LocaText" END WHERE "LocaId" = 'Heilmagier';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Roundhouse Blow is a defensive strike against multiple attackers.\n\nED Cost: 25 EP\nRequires: ST 15, CO 12, SA Mighty Blow, SA Offensive Combat I' THEN 'The Roundhouse Blow is a defensive strike against multiple attackers.\n\nED Cost: 20 EP\nRequires: CO 13, AG 13, SA Mighty Blow' ELSE "LocaText" END WHERE "LocaId" = 'InfoBefreiungsschlag';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = '\nThis spell suddenly removes all the warmth from the target''s body, lowering his or her combat stats and attributes considerably.\n\nEffects: AV, PA, DV each -4,\nIN, AG, DE, ST each -4\nDamage: SP* SP\nSpell Duration: 15 secs\nCost: 9 AP\nModifier: No' THEN '\nThis spell suddenly removes all the warmth from the target''s body, lowering his or her combat stats and attributes considerably.\n\nEffects: AV, PA, DV each -4,\nIN, AG, DE, ST each -4\nDamage: SP* HP\nSpell Duration: 15 secs\nCost: 9 AP\nModifier: No' ELSE "LocaText" END WHERE "LocaId" = 'InfoCorpofrigoKaelteschok';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The outcome of a battle often depends on the combatants'' tactics and fighting styles. Adopting a defensive combat stance will enable your hero to protect himself from attacks, while he studies his opponent''s tactics and develops an effective counter-strategy. Selecting a defensive stance will give your hero a bonus to their Parry Value (PA). The defensive combat stance is strenuous and the defender will expend a number of endurance points per parry. It is not possible to activate an offensive combat style simultaneously.\n\nEffect: +2 PA \nED Cost: 2 EP per parry in battle\nRequires: Base PA 6' THEN 'The outcome of a battle often depends on the combatants'' tactics and fighting styles. Adopting a defensive combat stance will enable your hero to protect himself from attacks, while he studies his opponent''s tactics and develops an effective counter-strategy. Selecting a defensive stance will give your hero a bonus to their Parry Value (PA) sacrificing somewhat the offense. The defensive combat stance is strenuous and the defender will expend a number of endurance points per parry. It is not possible to activate an offensive combat style simultaneously.\n\nEffect: PA +1\nED Cost: 2 EP per parry in battle\nRequires: Base PA 6' ELSE "LocaText" END WHERE "LocaId" = 'InfoDefensiverKampfstil1';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Adopting this stance will enhance your hero''s abilities in defensive combat. Warriors selecting a defensive combat style receive a bonus to their Parry Value (PA). The defensive combat style is strenuous and the defender will lose a number of endurance points per parry. It is not possible to select an offensive combat stance simultaneously.\n\nEffect: +4 PA \nED Cost: 4 EP per parry in battle\nRequires: Base PA 7, SA Defensive Combat I' THEN 'Adopting this stance will enhance your hero''s abilities in defensive combat. Warriors selecting a defensive combat style receive a bonus to their Parry Value (PA) sacrificing somewhat the offense. The defensive combat style is strenuous and the defender will lose a number of endurance points per parry. It is not possible to select an offensive combat stance simultaneously.\n\nEffect: PA +2\nED Cost: 2 EP per parry in battle\nRequires: Base PA 7, Defensive Combat I' ELSE "LocaText" END WHERE "LocaId" = 'InfoDefensiverKampfstil2';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Warrior is a master in the art of defensive combat. Warriors selecting a defensive combat style receive a bonus to their Parry Value (PA). The defensive combat style is strenuous and the defender will lose a number of endurance points per parry. It is not possible to select an offensive combat stance simultaneously.\n\nEffect: +6 PA \nED Cost: 6 EP per parry in battle\nRequires: Base PA 8, SA Defensive Combat I, SA Defensive Combat II' THEN 'The Warrior is a master in the art of defensive combat. Warriors selecting a defensive combat style receive a bonus to their Parry Value (PA) sacrificing somewhat the offense. The defensive combat style is strenuous and the defender will lose a number of endurance points per parry. It is not possible to select an offensive combat stance simultaneously.\n\nEffect: PA +4\nED Cost: 3 EP per parry in battle\nRequires: Base PA 8, Defensive Combat II' ELSE "LocaText" END WHERE "LocaId" = 'InfoDefensiverKampfstil3';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'This attack enables the hero to cast up to four throwing knives or throwing stars at a target. Success and the damage incurred is checked on a per throw basis.\n\nEffect: 4 throwing knife attacks, DP are calculated separately, opponent penalized -8 DV\nED Cost: 19 EP\nRequires: AG 14, DE 14, Base RC 8, SA Aimed Throw' THEN 'This attack enables the hero to cast up to four throwing knives at once towards a target. Success and the damage incurred is checked on a throw per throw basis. It cannot be performed with throwing axes.\n\nEffect: 4 throwing knife attacks with -8 PA, DP is calculated separately.\nED Cost: 15 EP\nRequires: DE 14, SA Aimed Throw' ELSE "LocaText" END WHERE "LocaId" = 'InfoEisenhagel';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'This is a deceptive strike in which the attacker shifts the angle of attack in order to slip past the opponent''s guard. A feint reduces the defender''s armor value and hinders them from parrying.\n\nEffect: Parry -4, AR -2\nEU Cost: 13 EP\nRequires: AG 12' THEN 'This is a deceptive strike in which the attacker shifts the angle of attack in order to slip past the opponent''s guard. A feint reduces the defender''s armor value and hinders them from parrying.\n\nEffect: Parry -4, AR 3/4\nEU Cost: 10 EP\nRequires: AG 12' ELSE "LocaText" END WHERE "LocaId" = 'InfoFinte';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Lunge is a thrust directed at a vulnerable and preferably unprotected part of the opponent''s body. The only defense against a Lunge is to parry.\n\nEffect: Parry -4, ignore AR, +1 Wound\nED Cost: 19 EP\nRequires: SA Feint' THEN 'The Lunge is a thrust directed at a vulnerable and preferably unprotected part of the opponent''s body. The only defense against a Lunge is to parry.\n\nEffect: Parry -4, ignore AR, +1 Wound\nED Cost: 15 EP\nRequires: CO 12, IN 12, AG 13, SA Feint' ELSE "LocaText" END WHERE "LocaId" = 'InfoGezielter Stich';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Aimed Shot enables an archer to focus his attention on a target and to aim his shot at a vulnerable point in the target''s armor. Aimed Shot halves the target''s Armor Rating (AR).\n\nEffect: AR/2\n\nED Cost: 15 EP\nRequires: Base RC 7' THEN 'Aimed Shot enables an archer to focus his attention on a target and to aim his shot at a vulnerable point in the target''s armor. Aimed Shot halves the target''s Armor Rating (AR).\n\nEffect: AR/2\n\nED Cost: 10 EP\nRequires: DE 10' ELSE "LocaText" END WHERE "LocaId" = 'InfoGezielterSchuss';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Strike of Wrath is the most powerful attack. It causes massive damage but requires considerable strength and endurance.\n\nEffect: DP x 3, opponent must test ST or be knocked to the ground\nED Cost: 30 EP\nRequires: CO 15, Base AV 9, SF Mighty Blow, SA Throw Down, SA Offensive Combat I, SA Offensive Combat 2' THEN 'The Strike of Wrath is the most powerful attack. It causes massive damage but requires considerable strength and endurance. Because of its power, the opponent will not parry the strike so easily.\n\nEffect: Parry -4, DP x 3, opponent must test ST or be knocked to the ground\nED Cost: 30 EP\nRequires: CO 15, CN 14, SA Knock Down' ELSE "LocaText" END WHERE "LocaId" = 'InfoHammerschlag';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'This aggressive combat technique allows the hero to carry out three consecutive strikes, only one of which can be parried.\n\nEffect: 3 attacks, only the first attack may be parried\nED Cost: 21 EP\nRequires: Base AV 8, SA Feint, SA Offensive Combat Style I' THEN 'This extremely aggressive combat technique allows the hero to carry out three consecutive strikes, only one of which can be parried (but they can miss). Skillful swordplay disorients the target, that exposes unprotected parts of the body while trying to defend, armor of the target is therefore halved.\n\nEffect: AR/2, 3 attacks\n\nED Cost: 20 EP\nRequires: CO 14, DE 13, ST 13, IN 13, SA Feint' ELSE "LocaText" END WHERE "LocaId" = 'InfoKlingensturm';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Wall of Blades is an advanced parrying technique enabling the hero to carry out an additional 4 parries over the next 15 combat rounds and defend himself against superior numbers.\n\nEffect: 4 extra parries over 15 CR\nED Cost: 20 EP\nRequires: SA Master Parry, SA Defensive Combat I' THEN 'The Wall of Blades is an advanced parrying technique enabling the hero to carry out an additional 4 parries over the next 15 combat rounds and defend himself against superior numbers.\n\nEffect: 4 extra parries over 15 CR\nED Cost: 20 EP\nRequires: AG 13, SA Master Parry' ELSE "LocaText" END WHERE "LocaId" = 'InfoKlingenwand';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The attacker puts all his strength into this massive ranged attack, which causes double damage if successful.\n\nEffect: 2 x DP\nED Cost: 19 EP\nRequires: ST 15, Base RC 8, SA Aimed Throw' THEN 'The attacker aims very carefully and makes a strong and deadly throw that will throw the opponent to the ground if it is unable to prevent the fall with a test against half of their Strength (ST)\n\nEffect: 3 x DP, Test ST or knocked down for 1 CR.\nED Cost: 15 EP\nRequires: DE 11, ST 14, SA Aimed Throw' ELSE "LocaText" END WHERE "LocaId" = 'InfoKraftwurf';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Thanks to his long years of experience the Master Crossbowman can reload a crossbow very quickly. This skill does not cost any Endurance Points and is permanently activated once purchased.\n\nEffect: Reloading a crossbow costs one action less.\nED Cost: none\nRequires:Base RC 8, SA Aimed Shot' THEN 'Thanks to his long years of experience the Master Crossbowman can reload a crossbow very quickly. This skill does not cost any Endurance Points and is permanently activated once purchased.\n\nEffect: Reloading a crossbow costs 1 CR less.\nED Cost: none\nRequires:Base RC 8, SA Aimed Shot' ELSE "LocaText" END WHERE "LocaId" = 'InfoLademeister';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'This is a simple parry that will prevent an opponent from striking the hero in the next combat round.\n\nEffect: Parry and Dodge maneuvers will always be successful for the next 15 combat rounds.\nED Cost: 15 EP\nRequires: Base PA 8' THEN 'This ability will allow the hero to focus on the next incoming attack with intense concentration. The concentration will cause some exhaustion, but the warrior will be successfully in the next dodge or parry maneuver.\n\nEffect: A Parry or Dodge maneuver will be succeed automatically during the next 15 combat rounds.\nED Cost: 10 EP\nRequires: Base PA 8, IN 13' ELSE "LocaText" END WHERE "LocaId" = 'InfoMeisterParade';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Master Marksman enables an archer to focus his entire attention on a target and to aim his shot at a vulnerable and unprotected part of the target''s body. The Master Marksman is an all-or-nothing shot which is capable of killing an opponent on the spot, but which also robs the archer of his energy reserves.\n\nEffect: 2x DP, ignore AR, +2 Wounds\nED Cost: 27 EP\nRequires: Base RC 9, SA Marksman' THEN 'Master Marksman enables an archer to focus his entire attention on a target and to aim his shot at a vulnerable and unprotected part of the target''s body. Effect: 2x DP, ignore AR, +2 Wounds\nED Cost: 25 EP\nRequires: DE 14, SA Marksman' ELSE "LocaText" END WHERE "LocaId" = 'InfoMeisterschuetze';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Master Throw is an extremely powerful attack - the sheer force of the blow can hurl a target to the ground. The attack inflicts severe damage and the target is thrown to the ground if it is unable to prevent the fall with a test against half of their Strength (ST). The Master Throw is an all-or-nothing throw. While it can be lethal, it also robs the thrower of his energy reserves.\n\nEffect: 2 x DP, Test ST or be thrown for 2 CR\nED Cost: 25 EP\nRequires: ST 15, Base RC 8, SA Aimed Throw, SA Power Throw' THEN 'The Master Throw is an extremely powerful attack that inflicts severe damage, a nasty wound, ignores the opponent''s armor and will stun it (CN/2 to resist).\n\nEffect: 2 x DP, +1 Wound, Test CN/2 or stunned for 3 CR, ignore AR\nED Cost: 25 EP\nRequires: DE 13, SA Power Throw' ELSE "LocaText" END WHERE "LocaId" = 'InfoMeisterwurf';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'This is an extremely powerful blow - its sheer force throws the opponent to the ground. The defender can test against half of its Strength (ST) to prevent a fall.\n\nEffect: Test ST/2 or 2 CR thrown\nED Cost: 14 EP\nRequires: Base AV 8, SA Mighty Blow, SA Offensive Combat I,' THEN 'This is an extremely powerful blow - its sheer force throws the opponent to the ground. The defender can test against half of its Strength (ST) to prevent a fall.\n\nEffect: Test ST/2 or 2 CR thrown\nED Cost: 10 EP\nRequires: ST 15, CO 13, SA Mighty Blow' ELSE "LocaText" END WHERE "LocaId" = 'InfoNiederwerfen';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The outcome of a battle often depends on the combatants'' choice of tactics. A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat I will give your hero a bonus to its Attack Value (AV). An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: +2 AV\nEd Cost: 2 EP per attack in battle\nRequires: Base AV 7' THEN 'The outcome of a battle often depends on the combatants'' choice of tactics. A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat I will give your hero a bonus to its Attack Value (AV) sacrificing somewhat the defense. An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: AV +1\nEd Cost: 2 EP per attack in battle\nRequires: Base AV 7' ELSE "LocaText" END WHERE "LocaId" = 'InfoOffensiverKampfstil1';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat II will give your hero a bonus to its Attack Value (AV). An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: +4 AV\nEd Cost: 4 EP per attack in battle\nRequires: Base AV 8, Offensive Combat I' THEN 'A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat II will give your hero a bonus to its Attack Value (AV) sacrificing somewhat the defense. An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: AV +2\nEd Cost: 2 EP per attack in battle\nRequires: Base AV 8, Offensive Combat I' ELSE "LocaText" END WHERE "LocaId" = 'InfoOffensiverKampfstil2';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat III will give your hero a bonus to its Attack Value (AV). An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: +6 AV\nEd Cost: 6 EP per attack in battle\nRequires: Base AV 9, SA Offensive Combat I, SA Offensive Combat II' THEN 'A hero who adopts an offensive combat style will try to pound his opponent into submission by landing as many blows as possible within a short period of time. Selecting Offensive Combat III will give your hero a bonus to its Attack Value (AV) sacrificing somewhat the defense. An aggressive fighting style is strenuous and each attack will cost endurance points. It is not possible to activate a defensive stance simultaneously.\n\nEffect: AV +4\nEd Cost: 3 EP per attack in battle\nRequires: Base AV 9, Offensive Combat II' ELSE "LocaText" END WHERE "LocaId" = 'InfoOffensiverKampfstil3';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'This attack enables the archer to fire two arrows at a target at once. The accuracy of the shots is checked individually, as is the damage incurred.\n\nEffect: shoots 2 arrows, opponent penalized -4 to DV\nED Cost: 20 EP\nRequires: RC Basis 8, SA Aimed Shot' THEN 'This attack enables the archer to fire two arrows at a target at once. The accuracy of the shots is checked individually, as is the damage incurred.\n\nEffect: shoots 2 arrows, opponent penalized -4 to DV\nED Cost: 12 EP\nRequires: DE 14, SA Aimed Shot' ELSE "LocaText" END WHERE "LocaId" = 'InfoPfeilhagel';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Marksman enables an archer to focus his attention on a target and to aim his shot at a vulnerable and unprotected part of the target''s body. Marksman ignores the target''s Armor Rating (AR) and automatically inflicts a wound.\n\nEffect: ignore AR, +1 Wound\nED Cost: 22 EP\nRequires: Base RC 8, SA Aimed Shot' THEN 'Marksman enables an archer to focus his attention on a target and to aim his shot at a vulnerable and unprotected part of the target''s body. Marksman ignores the target''s Armor Rating (AR) and automatically inflicts a wound.\n\nEffect: ignore AR, +1 Wound\nED Cost: 17 EP\nRequires: DE 12, SA Aimed Shot' ELSE "LocaText" END WHERE "LocaId" = 'InfoScharfschuetze';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Mortal Blow is a massive blow aimed at an unprotected part of the opponent''s body. The Mortal Blow is almost impossible to parry and causes massive damage. It is a strenuous attack and costs Endurance Points.\n\nEffect: Parry -6, DP x 2, ignore AR, +2 Wounds\nED Cost: 30 EP\nRequires: CO 15, SA Feint, SA Thrust, SA Offensive Combat 1' THEN 'The Mortal Blow is a massive blow aimed at an unprotected part of the opponent''s body. The Mortal Blow is almost impossible to parry and causes massive damage. It is a strenuous attack and costs Endurance Points.\n\nEffect: Parry -6, DP x 2, ignore AR, +2 Wounds\nED Cost: 25 EP\nRequires: CO 15, IN 15, SA Lunge' ELSE "LocaText" END WHERE "LocaId" = 'InfoTodesstoss';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Rushing an opponent can force him to lose his balance. It does not cause any damage. The defender can use half of their Agility (AG) to prevent a fall.\n\nEffect: Test AG/2 or 2 CR thrown, this attack cannot be parried\nED Cost: 22 EP\nRequires: ST 12, SA Feint, SA Offensive Combat I' THEN 'Rushing an opponent can force him to lose his balance. It does not cause any damage. The defender can use half of their Agility (AG) to prevent a fall.\n\nEffect: Test AG/2 or 2 CR thrown, this attack cannot be parried\nED Cost: 15 EP\nRequires: CO 11, IN 12, AG 11' ELSE "LocaText" END WHERE "LocaId" = 'InfoUmreissen';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The attacker takes careful aim and attempts to hit an unprotected area of his target''s body. The defender''s Armor Rating is reduced by half.\n\nEffect: AR/2\n\nED Cost: 10 EP\nRequires: Base RC 7' THEN 'The attacker takes careful aim and attempts to hit an unprotected area of his target''s body. The defender''s Armor Rating is reduced by half.\n\nEffect: AR/2\n\nED Cost: 5 EP\nRequires: DE 10' ELSE "LocaText" END WHERE "LocaId" = 'InfoWeitwurf';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'This advanced fighting technique channels the force of an opponent''s blow back into a powerful counter-attack. The force of the opponent''s blade is absorbed and channeled back towards the opponent in one fluid and devastating movement.\n\nEffect: All Parry and Dodge maneuvers will be successful for the next 15 combat rounds. The hero''s counter-attack cannot be parried.\nED Cost: 25 EP\nRequires: Base PA 9, SA Master Parry, SA Wall of Blades, SA Defensive Combat I, SA Defensive Combat II' THEN 'This advanced fighting technique channels the force of an opponent''s blow back into a powerful counter-attack. The force of the opponent''s blade is absorbed and channeled back towards the opponent in one fluid and devastating movement.\n\nEffect: Two Parry and Dodge maneuvers will be successful for the next 15 combat rounds. The hero''s counter-attack cannot be parried.\nED Cost: 25 EP\nRequires: IN 14, AG 14, SA Wall of Blades' ELSE "LocaText" END WHERE "LocaId" = 'InfoWindmuehle';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = '{0:i}W+{1:i} with {2:s} {3:i}' THEN '{0:i}D+{1:i} with {2:s} {3:i}' ELSE "LocaText" END WHERE "LocaId" = 'InfoWindowTotalDamage{0:i}{1:i}{2:s}{3:i}';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The Mighty Blow is a massive strike aimed at the opponent''s head which can cause severe damage. Heroes must have Endurance Points available to carry out a Mighty Blow.\n\nEffect: DP x 2\nEU cost: 20 EP\nRequires: ST 12' THEN 'The Mighty Blow is a massive strike aimed at the opponent''s head which can cause severe damage. Parrying this blow may not be as easy as usual.\n\nEffect: DP x 2, Parry -1\nEU cost: 15 EP\nRequires: ST 13' ELSE "LocaText" END WHERE "LocaId" = 'InfoWuchtschlag';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Thunderbolt' THEN 'Fulminictus' ELSE "LocaText" END WHERE "LocaId" = 'Item_fulminictus_long';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Thunderbolt' THEN 'Fulminictus' ELSE "LocaText" END WHERE "LocaId" = 'Item_fulminictus_short';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Culminatio Ball of Lightning' THEN 'Kulminatio' ELSE "LocaText" END WHERE "LocaId" = 'KulminatioKugelblitz';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The healing mage completed his education at the Donnerbach academy, an Elfish-influenced school that focuses on the healing arts. Healing mages are poor fighters but compensate for this with their advanced skills in healing and boosting the powers of other members of the party.' THEN 'The wizard completed his education at the Donnerbach academy, an Elfish-influenced school that focuses on the magic arts. Wizards are poor fighters but compensate for this with their advanced skills in the arcane arts and boosting the powers of other members of the party.' ELSE "LocaText" END WHERE "LocaId" = 'MI_HM_M_Info';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The healing mage completed her education at the Donnerbach academy, an Elfish-influenced school that focuses on the healing arts. Healing mages are poor fighters but compensate for this with their advanced skills in healing and boosting the powers of other members of the party.' THEN 'The wizard completed her education at the Donnerbach academy, an Elfish-influenced school that focuses on the magic arts. Wizards are poor fighters but compensate for this with their advanced skills in the arcane arts and boosting the powers of other members of the party.' ELSE "LocaText" END WHERE "LocaId" = 'MI_HM_W_Info';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The warrior is the archetypal hero, highly respected by the common people and bound to follow a comprehensive code of honor. He completed his training at an academy where he learned the arts of heavy weapons and armor, as well as how to dance at the royal court.' THEN 'The warrior is the archetypal hero, highly respected by the common people and bound to follow a comprehensive code of honor. Instead of staying home to practice his labour profession, he completed his training at an academy where he learned the arts of heavy weapons and armor, as well as how to dance at the royal court. ' ELSE "LocaText" END WHERE "LocaId" = 'MI_KR_M_Info';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The warrior is the archetypal hero, highly respected by the common people and bound to follow a comprehensive code of honor. She completed her training at an academy where she learned the arts of heavy weapons and armor, as well as how to dance at the royal court.' THEN 'The warrior is the archetypal hero, highly respected by the common people and bound to follow a comprehensive code of honor. Instead of staying home to practice her labour profession, she completed her training at an academy where she learned the arts of heavy weapons and armor, as well as how to dance at the royal court.' ELSE "LocaText" END WHERE "LocaId" = 'MI_KR_W_Info';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The archer is a ranged fighter trained in the army. He combats opponents from a distance with targeted, accurate shots. He is quick and nimble in his light armor. His training also provides him with a basic knowledge of archery.' THEN 'The Crossbowman is a ranged fighter trained in the army. He combats opponents from a distance with targeted, accurate shots. He is quick and nimble in his light armor. His training also provides him with a basic knowledge of bowyery.' ELSE "LocaText" END WHERE "LocaId" = 'MI_SG_M_Info';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The archer is a ranged fighter trained in the army. She combats opponents from a distance with targeted, accurate shots. She is quick and nimble in her light armor. Her training also provides her with a basic knowledge of archery.' THEN 'The Crossbowwoman is a ranged fighter trained in the army. She combats opponents from a distance with targeted, accurate shots. She is quick and nimble in her light armor. Her training also provides him with a basic knowledge of bowyery.' ELSE "LocaText" END WHERE "LocaId" = 'MI_SG_W_Info';
UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'The rogue grew up in the back alleys of the big city. He is an expert in urban survival but a fish out of water in the wilderness. Charismatic and skilled in the art of persuasion, he is an expert at judging a person''s character and intentions quickly and accurately. His preferred weapon is the dagger.' THEN 'The rogue grew up in the back alleys of the big city. He is an expert in urban survival but a fish out of water in the wilderness. Charismatic and skilled in the art of persuasion, he is an expert at judging a person''s character and intentions quickly and accurately.' ELSE "LocaText" END WHERE "LocaId" = 'MI_ST_M_Info';
