UPDATE "_Locale" SET "LocaText" = CASE WHEN "LocaText" = 'Tight buckskin pants. These close-fitting pants are ideal for moving through undergrowth at speed.' THEN 'These close-fitting leggings are ideal for moving through undergrowth at speed as well as for combat maneuvers. Apparently a spell causes extreme pain on those who wear them, so that only Elves can wear them safely.' ELSE "LocaText" END WHERE "LocaId" = 'infoid_hose_waldlaeufer';
