INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('Archer', 'Archer');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('Crossbowman', 'Crossbowman');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('Dom2AE5_name', 'Staff of the Druids');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('Nat2CH1_name', 'The Witch Robe');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('PeAW_name', 'Dodge bonus');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('PeWpPA_name', 'Weapon parry bonus');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('Sne2PP1_name', 'Shadow Armor');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('aw2_amulet_infoid', 'This pendant contains a magnificent gleaming heart-shaped ruby hanging on a gold chain. This artifact was brought to existence by an archwizard Ergonpandilus who was, unlike many wizards, a follower of the god Phex. As he cast the spell to enchant the artifact, the spell grew too strong to be handled by a mere mortal, thus taking his life. It is rumoured, that the ruby stone still holds the soul of its creator within, thus this pendant is also known as Heart of Ergonpandilus. The wearer of the pendant will feel his reflexes quickened, when someone threatens his life, like someone would guide the wearers moves.\nEffect: +2 DV');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('aw2_amulet_lookat', 'Pendant of Phex');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_druid_staff', 'A gnarled staff made of an ancient oak root. The wielder of this weapon will feel special bond towards animals.\nEffects:\n +2 Domination Magic\n +5 Astral Energy');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_handschuhe_leder', 'Gloves made of hardened leather with metal plates sewn into them, thus adding the ability to parry incoming attacks by using the wrist.\nEffect: +1 PA');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_piercing_rapier', 'This small sword is very well balanced and has a very thin and sharp blade, which will find its way through most armors. It''s also very light and easy to handle.\nEffect: +1 DP');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_piercing_spear', 'Long lance with nasty triple-headed tip ideal piercing through armor.\nEffect: +3 DP');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_praios_scimitar', 'A masterwork scimitar with a gleaming sterling silver blade, imbued with the spirit of Praios, so that the wielder will keep standing on his or her feet, even against the fiercest blows.\nEffect: immune to knockdown');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_ravenwing_saber', 'A slender saber of dark Maraskan steel, ''liberated'' from a Horasian battle mage by the finest hands of the Dark Eye. Faint runes along the fuller channel astral power into its bearer, and it is light enough to fight beside a shield.

Effect: AE +10');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_shadow_armor', 'This dark armor is made of finest black silk and dark leather. It feels very light and soft. Armor like this surely helps hiding in the shadows and move without a sound, like the shadow.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_tulamidian_dagger', 'Tulamidian dagger made by the people from deserts far away. During the daylight, the weapon looks like any other weapon, but under a moonlight it reveals itself by emiting silvery light indicating its great power within. The exceptional sharp curved blade can pierce many armors like the butter.\nEffect: +1 DP');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_witch_hat', 'This black silk hat was once worn by a great witch. This nasty hat will bless its wearer with a hightened sixth sense.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_witch_robe', 'A very beautiful black silk robe decorated with symbols that can only be related to witches. The character wearing this robe will feel close connection with the nature.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('infoid_wounding_dagger', 'Long dagger with menacing blade. There is etched word ''Bleeder'' on the hilt and the blade is decorated with symbols and runes.\nEffect: 5% chance of wounds');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_druid_staff', 'Staff of the Druids');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_piercing_rapier', 'Master''s Small Sword');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_piercing_spear', 'Death Lance');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_praios_scimitar', 'Light of Praios');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_ravenwing_saber', 'Ravenwing Saber');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_shadow_armor', 'Shadow Armor');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_tulamidian_dagger', 'Dagger of the Night');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_witch_hat', 'The Witch Hat');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_witch_robe', 'The Witch Robe');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('lookat_wounding_dagger', 'Bleeder');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_Archer_info_M', 'The Novadi Archer is an especially skilled longbowman, trained in the rough deserts of the south of Aventuria. His eyesight and accuracy are legendary, and the arts of both bowmanship and bowyery hold very few secrets for him.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_Archer_info_W', 'The Novadi Archer is an especially skilled longbowman, trained in the rough deserts of the south of Aventuria. Her eyesight and accuracy are legendary, and the arts of both bowmanship and bowyery hold very few secrets for her.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_amazon_D', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_amazon_N', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_archer_D', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_archer_N', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_battlemage_D', 'The battlemage is especially skilled in battle spells (+1) and buffing spells (+1), and can handle most weapons better than other wizardly classes. In the other realms of magic, though, his preparation is not as thorough.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_battlemage_N', 'Sword & Sorcery');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_charlatan_D', 'The charlatan can adapt to unfamiliar social settings and foreign cultures with remarkable ease and can quickly establish a rapport with others. When not chatting, the charlatan shows a clear predilection for light weapons and skill boosting spells.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_charlatan_N', 'Social Chamaleon');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_elementalist_D', 'An Elementalist is almost a pure mage, and a one that prefers unleashing on foes the power of fire, or summoning Djinns or other supernatural creatures.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_elementalist_N', 'Power of the elements');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_fighter_elf_D', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_fighter_elf_N', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_jost_D', 'Jost has received a special training, and is more skilled than most of his battlemage colleagues in melee combat and battle spells.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_jost_N', 'Battlemage Training');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_merc_D', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_merc_N', '');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_metamage_D', 'A Metamage favours spells that alter reality, rather than dealing raw damage, and excels in the necromantic arts. As for most Tulamides, the saber is his weapon of choice.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_metamage_N', 'Necromancer');
