INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_sapper_D', 'The sapper is very skilled in many Artisan Talents and can master Bowyer, Blacksmith, Disarm Traps and Pick Locks with ease.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_sapper_N', 'Artisan Talents Bonus');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_spellweaver_D', 'The most expert in the arcane arts among the elven kin, a Spellweaver receives a bonus in several spells, but also a penalty for most martial weapons.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_spellweaver_N', 'Elven Mage');
