INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_wizard_D', 'The wizard finds it difficult (-2) to handle weapons that are bigger than a dagger, or heavier than a staff, especially true for two-handed weapons (-3). On the other hand, wizards are proficient in all magic schools.');
INSERT OR IGNORE INTO "_Locale" ("LocaId", "LocaText") VALUES ('z_wizard_N', 'Way of the Wizard');
